SourceCode.Declaration:
/// <summary>
/// Cycle counting: one counting journal per enabled warehouse (HSMobileOpsCountWarehouse), holding the items
/// due by their counting group. The lines come from D365FO's own "Create by counting group"
/// (InventCountCreate), so the counting code and interval (Period, Zero, Minimum) and "Lock items
/// during count" in Inventory parameters behave exactly as they do in D365FO. An item with no
/// counting group is not due.
///
/// A warehouse whose last journal is still open gets no new one: its lines would only pile up,
/// and with locking on the items are already held by the open one.
///
/// Safe after a crash. The lines are written in one transaction, so a server restart leaves only an
/// empty journal header, which the next run removes; the batch job is retryable, so the framework
/// runs it again; and a warehouse held by a job that is over is free to take. A run that dies after
/// the lines landed is picked up where it stopped: the next run finishes that journal, and does
/// not make a second.
/// </summary>
class HSMobileOpsCountJournalCreateBatch extends SysOperationServiceBase
{
}

Method.Source:
/// <summary>Every enabled warehouse in every company; one failing does not stop the others.</summary>
public void createJournals()
{
    HSMobileOpsCountWarehouse row;

    while select crossCompany DataAreaId, Warehouse from row
        where row.CycleEnabled == NoYes::Yes
    {
        HSMobileOpsCountJournalCreateBatch::runWarehouse(row.DataAreaId, row.Warehouse);
    }
}

private static void runWarehouse(DataAreaId _company, InventLocationId _warehouse)
{
    InventJournalId journalId;
    int             lines;
    str             message;
    str             assortmentResult;
    int             infologFrom = infologLine();
    int             assortmentFrom;
    InventJournalId interrupted;

    changecompany (_company)
    {
        try
        {
            interrupted = HSMobileOpsCountJournalCreateBatch::interruptedJournal(_warehouse);
            if (!HSMobileOpsCountJournalCreateBatch::claim(_warehouse))
            {
                return;
            }
            HSMobileOpsCountJournalCreateBatch::removeEmptyJournals(_warehouse);
            message = interrupted ? '' : HSMobileOpsCountJournalCreateBatch::stillOpen(_warehouse);
            if (!message)
            {
                journalId = interrupted ? interrupted : HSMobileOpsCountJournalCreateBatch::createJournal(_warehouse);
                HSMobileOpsCountJournalCreateBatch::noteJournal(_warehouse, journalId);
                if (HSMobileOpsCountWarehouse::find(_warehouse).AssortmentBased)
                {
                    // The stock lines are good whatever happens here: the journal still gets
                    // its dual marking, and the reason goes on the warehouse's last result.
                    assortmentFrom = infologLine();
                    try
                    {
                        assortmentResult = HSMobileOpsCountAssortment::applyToJournal(journalId, _warehouse);
                    }
                    catch (Exception::Error)
                    {
                        assortmentResult = strFmt('Assortment not applied: %1', HSMobileOpsCountJournalCreateBatch::errorsSince(assortmentFrom));
                    }
                }
                lines     = HSMobileOpsCountJournalCreateBatch::lineCount(journalId);
                if (lines)
                {
                    message = strFmt(HSMobileOpsCountDualEngine::markDualLines(journalId, _warehouse) ? '%1 lines to count twice' : '%1 lines to count', lines);
                    if (assortmentResult)
                    {
                        message += '. ' + assortmentResult;
                    }
                }
                else
                {
                    HSMobileOpsCountJournalCreateBatch::deleteJournal(journalId);
                    journalId = '';
                    message   = 'Nothing is due';
                }
            }
            else
            {
                journalId = HSMobileOpsCountWarehouse::find(_warehouse).LastJournalId;
                lines     = HSMobileOpsCountJournalCreateBatch::lineCount(journalId);
            }
        }
        catch (Exception::Error)
        {
            message = strFmt('Failed: %1', HSMobileOpsCountJournalCreateBatch::errorsSince(infologFrom));
            if (infologLine() <= infologFrom)
            {
                message = 'Failed with no message from D365FO';
            }
        }

        HSMobileOpsCountJournalCreateBatch::writeResult(_warehouse, journalId, lines, message);
    }
}

/// <summary>
/// What D365FO said since the given infolog line, in order. Its last line is often only
/// "Update has been canceled"; the reason is the one before it.
/// </summary>
public static str errorsSince(int _fromLine)
{
    str text;
    int i;

    for (i = _fromLine + 1; i <= infologLine(); i++)
    {
        text += (text ? ' ' : '') + strReplace(infolog.text(i), '\t', ' ');
    }
    return text;
}

/// <summary>
/// The journal a run was building when it died, read before this run claims the warehouse: still
/// marked running, with an open journal noted that has its lines. Nothing to resume otherwise.
/// </summary>
private static InventJournalId interruptedJournal(InventLocationId _warehouse)
{
    HSMobileOpsCountWarehouse row = HSMobileOpsCountWarehouse::find(_warehouse);
    InventJournalTable        journalTable;

    if (row.LastMessage != HSMobileOpsCountJournalCreateBatch::runningText() || !row.LastJournalId)
    {
        return '';
    }
    journalTable = InventJournalTable::find(row.LastJournalId);
    return (journalTable.RecId && !journalTable.Posted && HSMobileOpsCountJournalCreateBatch::lineCount(row.LastJournalId))
        ? row.LastJournalId
        : '';
}

/// <summary>On the row as soon as the lines are in, so a run that dies from here can be resumed.</summary>
private static void noteJournal(InventLocationId _warehouse, InventJournalId _journalId)
{
    HSMobileOpsCountWarehouse row;

    ttsbegin;
    row = HSMobileOpsCountWarehouse::find(_warehouse, true);
    if (row.RecId)
    {
        row.LastJournalId = _journalId;
        row.update();
    }
    ttscommit;
}

/// <summary>
/// Only one run works a warehouse at a time, or both would find no open journal and make one.
/// The holder's job is on the row: a job that is over, or this one being run again after a
/// crash, does not hold it. Older than two hours is a run that died whatever its job says.
/// Replaced by the result when it ends.
/// </summary>
private static boolean claim(InventLocationId _warehouse)
{
    HSMobileOpsCountWarehouse row;
    BatchHeader      currentBatch = BatchHeader::getCurrentBatchHeader();
    RefRecId         currentJob = currentBatch ? currentBatch.parmBatchHeaderId() : 0;
    boolean          won;

    ttsbegin;
    select pessimisticLock firstOnly row
        where row.Warehouse == _warehouse;
    if (row.RecId
     && (row.LastMessage != HSMobileOpsCountJournalCreateBatch::runningText()
      || DateTimeUtil::getDifference(DateTimeUtil::utcNow(), row.LastRunUtc) > 7200
      || (currentJob && row.RunningBatchJobId == currentJob)
      || !HSMobileOpsCountJournalCreateBatch::jobAlive(row.RunningBatchJobId)))
    {
        row.LastRunUtc        = DateTimeUtil::utcNow();
        row.LastMessage       = HSMobileOpsCountJournalCreateBatch::runningText();
        row.RunningBatchJobId = currentJob;
        row.update();
        won = true;
    }
    ttscommit;

    return won;
}

private static boolean jobAlive(RefRecId _jobId)
{
    BatchJob batchJob;

    if (!_jobId)
    {
        return false;
    }
    select firstOnly RecId, Status from batchJob
        where batchJob.RecId == _jobId;
    return batchJob.RecId
        && batchJob.Status != BatchStatus::Finished
        && batchJob.Status != BatchStatus::Error
        && batchJob.Status != BatchStatus::Canceled;
}

/// <summary>
/// The header a crashed run left: its lines went back with the transaction. Only this job's
/// own kind, by journal name, warehouse and description, and only with no lines at all.
/// </summary>
private static void removeEmptyJournals(InventLocationId _warehouse)
{
    InventJournalTable journalTable;
    InventJournalTrans journalTrans;
    str                ownDescription = strFmt('Cycle count - %1 - *', _warehouse);

    ttsbegin;
    while select forUpdate journalTable
        where journalTable.JournalNameId    == HSMobileOpsCountWarehouse::find(_warehouse).journalName()
           && journalTable.InventLocationId == _warehouse
           && journalTable.Posted           == NoYes::No
           && journalTable.Description      like ownDescription
        notexists join journalTrans
            where journalTrans.JournalId == journalTable.JournalId
    {
        journalTable.delete();
    }
    ttscommit;
}

private static str stillOpen(InventLocationId _warehouse)
{
    InventJournalId journalId = HSMobileOpsCountWarehouse::find(_warehouse).LastJournalId;
    InventJournalTable journalTable = journalId ? InventJournalTable::find(journalId) : null;

    return (journalTable.RecId && !journalTable.Posted)
        ? strFmt('%1 is still open: no new journal', journalId)
        : '';
}

private static InventJournalId createJournal(InventLocationId _warehouse)
{
    HSMobileOpsCountWarehouse row = HSMobileOpsCountWarehouse::find(_warehouse);
    TransDate                 today = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());

    return HSMobileOpsCountJournalCreateBatch::createCountJournal(_warehouse, row.journalName(),
        strFmt('Cycle count - %1 - %2', _warehouse, date2StrUsr(today, DateFlags::None)), row.IncludeZeroOnHand);
}

/// <summary>
/// The header, then D365FO's own line creation: the items due by their counting group. The
/// warehouse filter is the one its dialog sets, which it only does for itself when opened from
/// a journal. (A wall-to-wall count builds its own lines from on-hand: HSMobileOpsCountWallToWall.)
/// </summary>
private static InventJournalId createCountJournal(InventLocationId _warehouse, InventJournalNameId _journalNameId,
    str _description, NoYes _includeZeroOnHand)
{
    InventLocation       inventLocation = InventLocation::find(_warehouse);
    InventJournalName    journalName = InventJournalName::find(_journalNameId);
    InventJournalTable   journalTable;
    JournalTableData     journalTableData;
    InventDimParm        dimParm;
    HSMobileOpsCountCreate        countCreate;
    Query                query;
    QueryBuildDataSource dataSource;
    TransDate            today = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());

    if (!inventLocation.RecId)
    {
        throw error(strFmt('No warehouse %1', _warehouse));
    }
    if (journalName.JournalType != InventJournalType::Count)
    {
        throw error(strFmt('%1 is not a counting journal name', _journalNameId));
    }

    ttsbegin;
    journalTable.clear();
    journalTable.initValue();
    journalTableData = JournalTableData::newTable(journalTable);
    journalTable.JournalId = journalTableData.nextJournalId();
    journalTableData.initFromJournalName(journalName);
    journalTable.InventSiteId     = inventLocation.InventSiteId;
    journalTable.InventLocationId = _warehouse;
    journalTable.Description      = subStr(_description, 1, 60);
    journalTable.insert();
    ttscommit;

    dimParm.ItemIdFlag           = NoYes::Yes;
    dimParm.InventSiteIdFlag     = NoYes::Yes;
    dimParm.InventLocationIdFlag = NoYes::Yes;
    dimParm.wMSLocationIdFlag    = NoYes::Yes;
    dimParm.InventBatchIdFlag    = NoYes::Yes;
    dimParm.InventSerialIdFlag   = NoYes::Yes;
    // Product dimensions too: without them a variant item's stock is left out of the journal.
    dimParm.ConfigIdFlag         = NoYes::Yes;
    dimParm.InventSizeIdFlag     = NoYes::Yes;
    dimParm.InventColorIdFlag    = NoYes::Yes;
    dimParm.InventStyleIdFlag    = NoYes::Yes;
    // Lines of items under warehouse management can't post without their status (seen on HSV001).
    dimParm.InventStatusFlag     = NoYes::Yes;

    countCreate = HSMobileOpsCountCreate::newCycleCount(journalTable.JournalId, today, dimParm, _includeZeroOnHand);

    query      = countCreate.queryRun().query();
    dataSource = query.dataSourceTable(tableNum(InventDim));
    SysQuery::findOrCreateQueryFilter(query, dataSource, fieldStr(InventDim, InventSiteId)).value(queryValue(inventLocation.InventSiteId));
    SysQuery::findOrCreateQueryFilter(query, dataSource, fieldStr(InventDim, InventLocationId)).value(queryValue(_warehouse));

    countCreate.run();

    return journalTable.JournalId;
}

private static int lineCount(InventJournalId _journalId)
{
    InventJournalTrans journalTrans;

    if (!_journalId)
    {
        return 0;
    }
    select count(RecId) from journalTrans
        where journalTrans.JournalId == _journalId;
    return int642int(journalTrans.RecId);
}

private static void deleteJournal(InventJournalId _journalId)
{
    InventJournalTable journalTable;

    ttsbegin;
    select forUpdate journalTable
        where journalTable.JournalId == _journalId;
    if (journalTable.RecId)
    {
        journalTable.delete();
    }
    ttscommit;
}

private static void writeResult(InventLocationId _warehouse, InventJournalId _journalId, int _lines, str _message)
{
    HSMobileOpsCountWarehouse row;

    ttsbegin;
    row = HSMobileOpsCountWarehouse::find(_warehouse, true);
    if (row.RecId)
    {
        row.LastRunUtc    = DateTimeUtil::utcNow();
        row.LastJournalId = _journalId;
        row.LastLineCount = _lines;
        row.LastMessage   = subStr(_message, 1, 250);
        row.RunningBatchJobId = 0;
        row.update();
    }
    ttscommit;
}
